mapper.select:
SELECT p.id, p.user_id, p.category_id, p.title, p.content, p.status, p.is_pinned, p.is_hot, p.like_count, p.comment_count, p.favorite_count, p.view_count, p.last_comment_time, p.create_time, p.update_time, u.id as author_id, u.username, u.avatar_url, pc.name as category_name, pc.code as category_code, (SELECT CASE WHEN pi.url LIKE 'data:%' THEN NULL ELSE pi.url END FROM post_image pi WHERE pi.post_id = p.id ORDER BY pi.sort_order DESC, pi.id ASC LIMIT 1) as cover_image FROM `post` p LEFT JOIN `user` u ON p.user_id = u.id LEFT JOIN `post_category` pc ON p.category_id = pc.id WHERE p.id IN
#{id}
AND p.status = 0 ORDER BY p.create_time DESC

SELECT COUNT(1)
FROM `post`
WHERE create_time >= #{since}

SELECT DATE(create_time) AS day, COUNT(1) AS value
FROM `post`
WHERE create_time >= #{startTime}
  AND create_time <= #{endTime}
GROUP BY DATE(create_time)
ORDER BY day ASC
